import data from "../data/sources-lab-rnc.json";
import type { ImageCredit, SourceLink, SourcePost, SourcesExtra } from "./aan-sources";
import { sourcePost } from "./sources";
import { tfhPost } from "./tfh-sources";

// RN Collins lab-book sources pages (Nov 24, 2026), review only for now. data/sources-lab-rnc.json is generated by
// RN_COLLINS hq/site/build_sources_lab_rnc.py from each package's sources_extra.json (the 16-section record), keyed by
// the post's schedule id. An entry names the post's existing sources page ("<account>/<slug>"); its references, image
// credits and article link come from that page's own data, and the record's annotated sources join the reference list.
// Drawn by components/lab-book.tsx (brand "rnc") at /sources/preview/rnc/<id>, which is a 404 on the live site.
type Entry = { id: string; page: string; date: string; title: string; series: string; extra: SourcesExtra; images?: ImageCredit[] };
const entries = (data as unknown as { posts: Record<string, Entry> }).posts;

export const labIds = () => Object.values(entries).sort((a, b) => (a.date || "9999").localeCompare(b.date || "9999") || a.id.localeCompare(b.id));

function base(page: string) {
  const [acct, slug] = page.split("/");
  return acct === "tfh" ? tfhPost(slug) : sourcePost(acct, slug);
}

export function labPost(id: string): SourcePost | undefined {
  const e = entries[id];
  if (!e) return undefined;
  const b = e.page ? base(e.page) : undefined;
  const research: SourceLink[] = [...(b?.research ?? [])];
  const seen = new Set(research.map((r) => r.url).filter(Boolean));
  // Each annotated source joins the reference list under the link its annotation uses (DOI, else free full text), and
  // leaves "Other sources" if the page listed it there.
  // One with neither is drawn from its annotation alone (lab-book brand "rnc").
  const annotations = (e.extra.annotations ?? []).map((a) => {
    const url = a.doi || a.open_access || "";
    if (url && !seen.has(url)) { research.push({ label: a.source, url }); seen.add(url); }
    return { ...a, doi: url || undefined };
  });
  return {
    slug: e.page || `rnc/${id}`, id: b?.id ?? id, title: b?.title ?? e.title, series: b?.series ?? e.series, date: b?.date ?? e.date,
    origin: b?.origin ?? null, research, other: (b?.other ?? []).filter((o) => !o.url || !seen.has(o.url)), images: b?.images ?? e.images ?? [],
    extra: { ...e.extra, annotations },
  };
}
